/**
 * @distilled.cloud/netbird -- NetBird SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model that
 * `scripts/convert.ts` converts from the OpenAPI spec. Everything else in this
 * folder is hand-written.
 *
 * @example
 * ```ts
 * import * as NetBird from "@distilled.cloud/netbird";
 *
 * const policies = yield* NetBird.listPolicies({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { NetBirdProtocol, type NetBirdOpError, type NetBirdOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts -- the ops actually raise the
// service-local classes.
export * from "./services/netbird.ts";
export {
  BadRequest,
  Conflict,
  Forbidden,
  NotFound,
  UnprocessableEntity,
} from "./services/netbird.ts";
